def get_money_spent(keyboards: list[int], drives: list[int], b: int) -> int:
    k_sorted = sorted(keyboards)
    d_sorted = sorted(drives, reverse=True)
    max_spent = -1
    j = 0
    for k in k_sorted:
        while j < len(d_sorted) and k + d_sorted[j] > b:
            j += 1
        if j < len(d_sorted):
            max_spent = max(max_spent, k + d_sorted[j])
    return max_spent
